package matrix

import (
	"errors"
	"strconv"
	"strings"
)

// Matrix is a rectangular grid of integers, stored row by row.
type Matrix [][]int

// New parses s as a matrix of integers. Rows are separated by newlines and
// elements within a row by whitespace. It returns an error if any row is
// empty, rows have differing lengths, or any element is not an integer.
func New(s string) (Matrix, error) {
	lines := strings.Split(s, "\n")
	m := make(Matrix, 0, len(lines))
	width := -1
	for _, line := range lines {
		fields := strings.Fields(line)
		if len(fields) == 0 {
			return nil, errors.New("matrix row is empty")
		}
		if width == -1 {
			width = len(fields)
		} else if len(fields) != width {
			return nil, errors.New("matrix rows have uneven lengths")
		}
		row := make([]int, len(fields))
		for i, f := range fields {
			n, err := strconv.Atoi(f)
			if err != nil {
				return nil, err
			}
			row[i] = n
		}
		m = append(m, row)
	}
	return m, nil
}

// Cols returns the columns of the matrix as an independent copy of the data.
func (m Matrix) Cols() [][]int {
	if len(m) == 0 {
		return nil
	}
	cols := make(Matrix, len(m[0]))
	for c := range cols {
		cols[c] = make([]int, len(m))
		for r := range m {
			cols[c][r] = m[r][c]
		}
	}
	return cols
}

// Rows returns the rows of the matrix as an independent copy of the data.
func (m Matrix) Rows() [][]int {
	rows := make(Matrix, len(m))
	for r := range m {
		rows[r] = make([]int, len(m[r]))
		copy(rows[r], m[r])
	}
	return rows
}

// Set sets the element at row, col to val. It reports whether the position
// is within the matrix.
func (m Matrix) Set(row, col, val int) bool {
	if row < 0 || row >= len(m) || col < 0 || col >= len(m[row]) {
		return false
	}
	m[row][col] = val
	return true
}
